import{_ as a,o as i,c as o,ae as n}from"./chunks/framework.YL6nI5ZP.js";const p=JSON.parse('{"title":"Hidráulica 1D","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/hidraulica/index.md","filePath":"es/explanation/hidraulica/index.md"}'),d={name:"es/explanation/hidraulica/index.md"};function l(r,e,s,c,t,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="hidraulica-1d" tabindex="-1">Hidráulica 1D <a class="header-anchor" href="#hidraulica-1d" aria-label="Permalink to &quot;Hidráulica 1D&quot;">​</a></h1><p>La descripción a nivel de ecuaciones del proceso de cálculo hidráulico 1D del motor de LocalSWMM, transcrita desde el código fuente del motor. Léelos en orden; los artículos posteriores se construyen sobre los anteriores.</p><ol><li><a href="./01-modelo-conceptual">Modelo conceptual</a> — alcance, modelo conceptual de nodos y enlaces, variables de estado, las cuatro formulaciones de tránsito.</li><li><a href="./02-componentes-del-modelo">Componentes del modelo</a> — datos de nodos, datos de enlaces, pendiente y longitud, alargamiento de conductos.</li><li><a href="./03-orquestacion-de-la-simulacion">Orquestación de la simulación</a> — el ciclo de avance temporal, relojes de escorrentía y tránsito, aportes laterales.</li><li><a href="./04-geometria-de-secciones">Geometría de secciones</a> — las cuatro relaciones geométricas, Manning y el factor de sección.</li><li><a href="./05-formulaciones-de-transito">Formulaciones de tránsito</a> — flujo permanente y onda cinemática.</li><li><a href="./06-solver-de-onda-dinamica">Solver de onda dinámica</a> — ecuaciones de St. Venant, diferencias finitas, la iteración de Picard.</li><li><a href="./07-kernel-de-momentum-de-enlaces">Kernel de momentum de enlaces</a> — velocidad, número de Froude, los seis términos de momentum, limitación de flujo.</li><li><a href="./08-continuidad-de-nodo">Continuidad de nodo</a> — actualizaciones explícita y semi-implícita, inundación y encharcamiento.</li><li><a href="./09-metodos-de-sobrenivel">Métodos de sobrenivel</a> — EXTRAN y ranura de Preissmann estática/dinámica.</li><li><a href="./10-estructuras-y-condiciones-de-borde">Estructuras y condiciones de borde</a> — bombas, orificios, vertederos, descargas, emisarios, divisores.</li><li><a href="./11-estabilidad-y-paso-de-tiempo">Estabilidad y paso de tiempo</a> — condición de Courant, balance de masa.</li><li><a href="./12-opciones-y-valores-por-defecto">Opciones y valores por defecto</a> — la superficie de configuración del motor.</li></ol><p>La fuente LaTeX original es <a href="./../../../sources/1d_hidraulica.tex">1d_hidraulica.tex</a>. El espejo en inglés está en <a href="/docs/explanation/hydraulics/">1D Hydraulics</a>.</p>',4)])])}const f=a(d,[["render",l]]);export{p as __pageData,f as default};
